package com.zajel.app.data;
import android.content.*;import android.security.keystore.*;import com.zajel.app.domain.UserSession;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.nio.charset.StandardCharsets;import java.security.*;import android.util.Base64;
public final class SecureSessionStore {private static final String ALIAS="zajel_session_key";private final SharedPreferences p;public SecureSessionStore(Context c){p=c.getSharedPreferences("zajel_session",Context.MODE_PRIVATE);}public void save(UserSession s){p.edit().putString("token",seal(s.accessToken)).putString("id",s.userId).putString("email",s.email).apply();}public UserSession read(){try{String t=p.getString("token","");if(t.isEmpty())return null;return new UserSession(open(t),p.getString("id",""),p.getString("email",""));}catch(Exception e){clear();return null;}}public void clear(){p.edit().clear().apply();}private String seal(String value)throws Exception{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(),new GCMParameterSpec(128,iv));byte[] encrypted=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[] all=new byte[iv.length+encrypted.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(encrypted,0,all,iv.length,encrypted.length);return Base64.encodeToString(all,Base64.NO_WRAP);}private String open(String value)throws Exception{byte[] all=Base64.decode(value,Base64.NO_WRAP);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,all,0,12));return new String(c.doFinal(all,12,all.length-12),StandardCharsets.UTF_8);}private SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return ((KeyStore.SecretKeyEntry)ks.getEntry(ALIAS,null)).getSecretKey();}}
